#!/usr/bin/env bash
# Run one measurement round: reset counters, sample the control API while
# viewers watch, then freeze an immutable snapshot in rounds/<label>/.
#
#   bash scripts/measure-round.sh <label> [duration_seconds]
#
# Duration defaults to 240s so the steady-state window (T+60s..T+180s) fits
# comfortably and the tail stays available for buffer/drain inspection.
#
# DO NOT EDIT THIS FILE (or any script it calls) WHILE A ROUND IS RUNNING.
# bash reads a script incrementally by byte offset, so a mid-run edit corrupts
# parsing of the remainder: observed as "break: only meaningful in a loop"
# followed by a syntax error, with a half-written artifact left behind.
set -euo pipefail
cd "$(dirname "$0")/.."

LABEL="${1:?usage: measure-round.sh <label> [duration_seconds]}"
DURATION="${2:-240}"
STEADY_FROM_S=60
STEADY_TO_S=180

# The steady window must fit inside the round. A shorter round would silently
# extend the window past the moment sampling stopped, and every live client
# would then look "offline at window end" — scoring a healthy round as unusable.
if (( DURATION < STEADY_TO_S + 10 )); then
  echo "duration ${DURATION}s is too short: the steady window is T+${STEADY_FROM_S}s..T+${STEADY_TO_S}s." >&2
  echo "use at least $((STEADY_TO_S + 10))s (default 240)." >&2
  exit 2
fi
PORT="${PORT:-8080}"
BASE="http://127.0.0.1:$PORT"
OUT="rounds/$LABEL"
ACCESS_LOG="logs/access.log"

mkdir -p "$OUT"

# A warm browser cache silently breaks the origin accounting: the P2P engine
# counts cached responses as "HTTP" while Caddy logs nothing, so the two accounts
# diverge and the round can never be judged. Refuse rather than produce a
# misleading artifact.
# Check a .ts segment, not the manifest: the manifest is always no-store, so
# probing it would always pass while segments stayed immutably cached.
FIRST_SEGMENT="$(curl -s "$BASE/hls/stream/index.m3u8" 2>/dev/null | grep -m1 '\.ts$' || true)"
SEGMENT_CACHE="$(curl -s -o /dev/null -D - "$BASE/hls/stream/${FIRST_SEGMENT:-seg_0000.ts}" 2>/dev/null \
  | tr -d '\r' | awk 'tolower($1)=="cache-control:"{print $2" "$3; exit}')"
if [[ "$SEGMENT_CACHE" != *no-store* ]]; then
  echo "segment Cache-Control is '$SEGMENT_CACHE' — measurement needs no-store." >&2
  echo "restart the stack first:" >&2
  echo "  bash scripts/stop.sh && SEGMENT_CACHE_CONTROL=no-store bash scripts/start.sh" >&2
  exit 2
fi

# Refuse to burn a round on pages that cannot report.
bash scripts/wait-ready.sh "${MIN_READY:-3}" "${READY_WAIT_S:-90}" || exit 2

START_MS="$(date +%s%3N)"
curl -fsS -X POST "$BASE/api/reset" \
  -H 'content-type: application/json' \
  -d "{\"label\":\"$LABEL\"}" >"$OUT/reset.json"

# Only media bytes written after this offset belong to this round.
[[ -f "$ACCESS_LOG" ]] || : >"$ACCESS_LOG"
ACCESS_OFFSET="$(wc -c <"$ACCESS_LOG")"
ACCESS_INO="$(stat -c %i "$ACCESS_LOG")"

echo "round '$LABEL' started at $START_MS (duration ${DURATION}s)"
echo "open http://<lan-ip>:$PORT/ on each device now; sampling every 2s..."

: >"$OUT/samples.jsonl"
deadline=$((START_MS + DURATION * 1000))
while :; do
  now="$(date +%s%3N)"
  body="$(curl -fsS "$BASE/api/stats" 2>/dev/null || echo '{}')"
  printf '{"polledAt":%s,"stats":%s}\n' "$now" "$body" >>"$OUT/samples.jsonl"
  [[ "$now" -ge "$deadline" ]] && break
  sleep 2
done

END_MS="$(date +%s%3N)"

# Ask the server for exact sliding windows: it aligns every client to the last
# sample at or before each boundary, so the windows are comparable across
# clients with different report phases. Clamped to END_MS so a round that ran
# long still measures only what actually happened.
STEADY_FROM_MS=$((START_MS + STEADY_FROM_S * 1000))
STEADY_TO_MS=$((START_MS + STEADY_TO_S * 1000))
(( STEADY_TO_MS > END_MS )) && STEADY_TO_MS=$END_MS

curl -fsS "$BASE/api/stats?from=$STEADY_FROM_MS&to=$STEADY_TO_MS" >"$OUT/steady.json"
curl -fsS "$BASE/api/stats?from=$START_MS&to=$END_MS" >"$OUT/clients.json"
curl -fsS "$BASE/api/health" >"$OUT/health.json"
cp logs/control.log "$OUT/server.log" 2>/dev/null || true

if [[ "$(stat -c %i "$ACCESS_LOG")" == "$ACCESS_INO" ]]; then
  tail -c +"$((ACCESS_OFFSET + 1))" "$ACCESS_LOG" >"$OUT/access.log"
else
  cp "$ACCESS_LOG" "$OUT/access.log"
fi

python3 - "$OUT" "$START_MS" "$END_MS" "$LABEL" <<'PY'
import json
import sys
from pathlib import Path

out = Path(sys.argv[1])
start_ms, end_ms, label = int(sys.argv[2]), int(sys.argv[3]), sys.argv[4]

steady = json.loads((out / "steady.json").read_text())
health = json.loads((out / "health.json").read_text())

media_bytes = 0
segment_requests = 0
for line in (out / "access.log").read_text().splitlines():
    try:
        entry = json.loads(line)
    except json.JSONDecodeError:
        continue
    uri = (entry.get("request") or {}).get("uri", "")
    if not uri.startswith("/hls/"):
        continue
    media_bytes += int(entry.get("size") or entry.get("bytes_written") or 0)
    if uri.endswith(".ts"):
        segment_requests += 1

window = steady.get("window", {})
summary = {
    "label": label,
    "startMs": start_ms,
    "endMs": end_ms,
    "health": health,
    "steady": {
        "from": window.get("from"),
        "to": window.get("to"),
        "clients": window.get("clients", []),
        "totals": window.get("total", {}),
        "p2pRatio": window.get("p2pRatio", 0.0),
    },
    "roundServerMediaBytes": media_bytes,
    "roundServerSegmentRequests": segment_requests,
}
(out / "summary.json").write_text(json.dumps(summary, indent=2) + "\n")

clients = summary["steady"]["clients"]
bytes_total = sum(c.get("downP2P", 0) + c.get("downHTTP", 0) for c in clients)
print(f"wrote {out}/summary.json: {len(clients)} clients, "
      f"steady P2P {summary['steady']['p2pRatio'] * 100:.1f}%, "
      f"{bytes_total / 1e6:.1f} MB player-side in window, "
      f"{media_bytes / 1e6:.1f} MB server media bytes for the round")
PY

echo "round '$LABEL' finished; judge it with: bash scripts/verify-round.sh $OUT"
